static void fastcd_ff_medium_bar_points_cd16(FastCDFFPacked16* restrict out,
        const FastCDFFPacked16* x, const FastCDFFPacked16* y, size_t n,
        FastCDFFPacked16* restrict work, const Context* restrict ctx) {
    size_t h = n / 2;
    fastcd_ff_medium_bar_node16(
            out, out + h * 16, x, x + h * 16, y, y + h * 16, h, work, ctx);
    FastCDFFPacked16 gv[32], dv[32], av[32], bv[32], kv[32];
    for (size_t k = 0; k < 32; k++) {
        size_t point = k % 16;
        gv[k] = x[h * 16 + point];
        dv[k] = y[h * 16 + point];
        av[k] = x[point];
        bv[k] = y[point];
        kv[k] = k < 16 ? 0 : UINT16_MAX;
    }
    Word gamma = _mm512_loadu_si512((const void*)(gv)),
         delta = _mm512_loadu_si512((const void*)(dv)),
         alpha = _mm512_loadu_si512((const void*)(av)),
         beta = _mm512_loadu_si512((const void*)(bv)),
         keep = _mm512_loadu_si512((const void*)(kv));
    Word sum = _mm512_setzero_si512(), dot = _mm512_setzero_si512();
    for (size_t i = 0; i < h; i += 2) {
        Word u = _mm512_loadu_si512((const void*)(x + i * 16)),
             v = _mm512_loadu_si512((const void*)(y + i * 16)),
             s = _mm512_loadu_si512((const void*)(x + (h + i) * 16)),
             t = _mm512_loadu_si512((const void*)(y + (h + i) * 16));
        if (i == 0) {
            u = _mm512_and_si512(u, keep);
            v = _mm512_and_si512(v, keep);
            s = _mm512_and_si512(s, keep);
            t = _mm512_and_si512(t, keep);
        }
        fastcd_ff_medium_bar_ValueLocal a =
                fastcd_ff_medium_bar_vlocal(u, v, s, t, gamma, delta, ctx);
        sum = add(sum, a.scalar, ctx);
        Word f = add(_mm512_loadu_si512((const void*)(out + i * 16)), a.first, ctx),
             g = sub(a.second, _mm512_loadu_si512((const void*)(out + (h + i) * 16)),
                     ctx);
        _mm512_storeu_si512((void*)(out + i * 16), f);
        _mm512_storeu_si512((void*)(out + (h + i) * 16), g);
    }
    FastCDFFPacked16 partial[32];
    _mm512_storeu_si512((void*)(partial), sum);
    FastCDFFPacked16 prime =
            (FastCDFFPacked16)_mm_cvtsi128_si32(_mm512_castsi512_si128(ctx->prime));
    for (size_t point = 0; point < 16; point++) {
        FastCDFFPacked16 a = 0;
        for (size_t k = point; k < 32; k += 16) {
            FastCDFFPacked16 b = a + partial[k];
            a = b >= prime ? b - prime : b;
        }
        out[h * 16 + point] = a;
    }
    for (size_t i = 0; i < n * 16; i += 32) {
        Word a = _mm512_loadu_si512((const void*)(x + i)),
             b = _mm512_loadu_si512((const void*)(y + i));
        dot = add(dot, multiply(a, b, ctx), ctx);
        Word term = add(multiply(alpha, b, ctx), multiply(beta, a, ctx), ctx);
        term = add(term, _mm512_loadu_si512((const void*)(out + i)), ctx);
        _mm512_storeu_si512((void*)(out + i), term);
    }
    Word aa = multiply(alpha, beta, ctx);
    aa = add(aa, aa, ctx);
    _mm512_storeu_si512((void*)(av), aa);
    _mm512_storeu_si512((void*)(partial), dot);
    for (size_t point = 0; point < 16; point++) {
        FastCDFFPacked16 a = 0;
        for (size_t k = point; k < 32; k += 16) {
            FastCDFFPacked16 b = a + partial[k];
            a = b >= prime ? b - prime : b;
        }
        FastCDFFPacked16 v = av[point] + prime - a;
        out[point] = v >= prime ? v - prime : v;
    }
}

